export function gradeAnswer(question,input){
  const text=String(input).trim().replace(/，/g,',');
  if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(text))return {valid:false,correct:false};
  const value=Number(text);
  return {valid:Number.isFinite(value),correct:Number.isFinite(value)&&Math.abs(value-question.answer)<=Math.max(question.tolerance,1e-10),value};
}
